sparksql:
MERGE INTO silver.customers t USING updates s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET *
WHEN NOT MATCHED THEN INSERT *;

snowflake:
MERGE INTO customers t USING updates s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET t.name = s.name
WHEN NOT MATCHED THEN INSERT (id, name) VALUES (s.id, s.name);

bigquery:
MERGE `project.dataset.customers` t USING updates s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET t.updated_at = CURRENT_TIMESTAMP()
WHEN NOT MATCHED THEN INSERT ROW;

trino:
MERGE INTO iceberg.db.customers t USING updates s ON t.id = s.id
WHEN MATCHED THEN UPDATE SET name = s.name
WHEN NOT MATCHED THEN INSERT VALUES (s.id, s.name);
